package com.p2p.escrow.repo;
import com.p2p.escrow.domain.*; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public final class Repositories { private Repositories(){} public interface Users extends JpaRepository<AppUser,UUID>{Optional<AppUser> findByEmail(String email);} public interface Orders extends JpaRepository<TradeOrder,UUID>{@Query("select o from TradeOrder o where o.status='OPEN'") List<TradeOrder> active(); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select o from TradeOrder o where o.id=:id") Optional<TradeOrder> lock(@Param("id") UUID id);} public interface Wallets extends JpaRepository<Wallet,UUID>{@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select w from Wallet w where w.userId=:user and w.asset=:asset") Optional<Wallet> lock(@Param("user") UUID user,@Param("asset") String asset); List<Wallet> findByUserId(UUID userId);} public interface Escrows extends JpaRepository<Escrow,UUID>{@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select e from Escrow e where e.id=:id") Optional<Escrow> lock(@Param("id") UUID id);} public interface Ledger extends JpaRepository<LedgerEntry,UUID>{} }
